create or replace function public.guard_vehicle_image_review_baseline() returns trigger language plpgsql security invoker set search_path = public, pg_temp as $$ declare b public.vehicle_image_review_baselines%rowtype; begin select * into b from public.vehicle_image_review_baselines where asset_id=old.id; if not found then return coalesce(new,old); end if; if tg_op='DELETE' then raise exception 'Vehicle image asset % has a review baseline; remove baseline explicitly before deletion',old.id; end if; if new.image_path is distinct from b.image_path or new.operator is distinct from old.operator or new.vehicle_type is distinct from old.vehicle_type or new.asset_status is distinct from old.asset_status then raise exception 'Vehicle image asset % is reviewed and baseline-protected; explicitly remove baseline first',old.id; end if; if b.metadata_lock_eligible and (new.formation_id is distinct from old.formation_id or new.car_id is distinct from old.car_id or new.is_generic is distinct from old.is_generic or new.asset_scope is distinct from old.asset_scope or new.livery is distinct from old.livery or new.theme is distinct from old.theme) then raise exception 'Vehicle image asset % identity metadata is locked; explicitly remove baseline first',old.id; end if; return new; end $$; drop trigger if exists vehicle_image_review_baseline_guard on public.vehicle_image_assets; create trigger vehicle_image_review_baseline_guard before update or delete on public.vehicle_image_assets for each row execute function public.guard_vehicle_image_review_baseline();
